-- The least-privilege user and the objects that reach through others. AGENT_RO is an operating-system
-- user of the container (run.sh creates it); it gets CONNECT and SELECT on two fixture tables, nothing else.
-- APP.SECRET is a table it may not read, APP.LEDGER one it may not write, and APP.ORDER_SEQ a sequence it may
-- not use: each object below reaches one of them with its owner's authority.
GRANT CONNECT ON DATABASE TO USER AGENT_RO;
GRANT SELECT ON APP.ORDERS TO USER AGENT_RO;
GRANT SELECT ON APP.CUSTOMERS TO USER AGENT_RO;
CREATE TABLE APP.SECRET (V VARCHAR(20));
INSERT INTO APP.SECRET VALUES ('owner-only');
CREATE TABLE APP.LEDGER (N INTEGER);
CREATE FUNCTION APP.READ_SECRET () RETURNS VARCHAR(20) LANGUAGE SQL READS SQL DATA RETURN (SELECT MAX(V) FROM APP.SECRET);
CREATE FUNCTION APP.WRITE_LEDGER () RETURNS TABLE (N INTEGER) LANGUAGE SQL MODIFIES SQL DATA BEGIN ATOMIC INSERT INTO APP.LEDGER VALUES (1); RETURN SELECT COUNT(*) FROM APP.LEDGER; END;
GRANT EXECUTE ON FUNCTION APP.WRITE_LEDGER TO USER AGENT_RO;
CREATE VIEW APP.CALLS_CODE AS SELECT APP.READ_SECRET() AS V FROM SYSIBM.SYSDUMMY1;
GRANT SELECT ON APP.CALLS_CODE TO USER AGENT_RO;
CREATE FUNCTION APP.MASK_NAME (NAME VARCHAR(100)) RETURNS VARCHAR(100) LANGUAGE SQL READS SQL DATA DETERMINISTIC NO EXTERNAL ACTION SECURED RETURN (SELECT MAX(V) FROM APP.SECRET);
CREATE MASK APP.CUSTOMERS_NAME ON APP.CUSTOMERS FOR COLUMN NAME RETURN CASE WHEN 1 = 1 THEN APP.MASK_NAME(NAME) ELSE NAME END ENABLE;
ALTER TABLE APP.CUSTOMERS ACTIVATE COLUMN ACCESS CONTROL;
GRANT USAGE ON SEQUENCE APP.ORDER_SEQ TO USER AGENT_RO;
